import {rangePlayback} from './topic-tools.js';
export function cells(values,active=[],done=[]){return `<div class="algorithm-cells">${values.map((v,i)=>`<span class="${active.includes(i)?'algorithm-active':done.includes(i)?'algorithm-done':''}"><small>${i}</small><b>${v===null?'—':v}</b></span>`).join('')}</div>`;}
export function traceLab(id,title,intro,frames,initial,body,legend='Blue outlines mark active input positions, index labels remain visible.'){return `<div id="${id}" class="topic-scene" data-algorithm-lab="${id}"><h3>${title}</h3><p>${intro}</p><label>Step <output data-step>${initial}</output> / ${frames.length-1}<input type="range" min="0" max="${frames.length-1}" step="1" value="${initial}" aria-label="${title} step"></label><div data-trace-body>${body(frames[initial])}</div><div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div><p class="topic-scenes-caption">Exact small input, not a speed benchmark. Step order follows the algorithm; playback is optional. ${legend}</p></div>`;}
export function mountTrace(article,id,frames,body){const lab=article.querySelector(`[data-algorithm-lab="${id}"]`);rangePlayback(article,lab,i=>{lab.querySelector('[data-step]').textContent=i;lab.querySelector('[data-trace-body]').innerHTML=body(frames[i]);},14000);}
